const src = $('Loop Over Search URLs').first().json;
const clean = (s, max = 300) => String(s || '').substring(0, max).replace(/[^\x20-\x7E]/g, '').replace(/\\/g, '/');
const seen = new Set();
const out = [];
for (const item of $input.all()) {
  const p = item.json;
  const url = String(p.public_profile_url || '').trim();
  if (!url || seen.has(url.toLowerCase())) continue;
  seen.add(url.toLowerCase());
  out.push({ json: {
    notion_page_id: src.notion_page_id,
    campaign_name: src.campaign_name,
    first_name: clean(p.first_name),
    last_name: clean(p.last_name),
    headline: clean(p.headline, 200),
    position1_role: clean(p.current_positions?.[0]?.role),
    position1_company: clean(p.current_positions?.[0]?.company),
    location: clean(p.location),
    industry: clean(p.current_positions?.[0]?.industry?.[0]),
    summary: clean(p.summary, 300),
    public_profile_url: url
  } });
}
return out;

const p = $('Loop Over Profiles').item.json;
let parsed = { score: 0, reason: 'parse error' };
try {
  let raw = $json.content?.[0]?.text || '{}';
  raw = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  parsed = JSON.parse(raw);
} catch (e) {}
return { json: { ...p, score: parsed.score || 0, reason: parsed.reason || '' } };

